--
local Players = game:GetService("Players") local ReplicatedStorage = game:GetService("ReplicatedStorage") local TweenService = game:GetService("TweenService") local UserInputService = game:GetService("UserInputService") local Workspace = game:GetService("Workspace") local LocalPlayer = Players.LocalPlayer local GuideModule = require(ReplicatedStorage:WaitForChild("GuideModule")) local Quests = require(ReplicatedStorage:WaitForChild("Quests")) local CombatController = require(ReplicatedStorage.Controllers:WaitForChild("CombatController")) local Remotes = ReplicatedStorage:WaitForChild("Remotes") local GetBestQuestNPC = Remotes:FindFirstChild("GetBestQuestNPC") local CommF_ = Remotes:FindFirstChild("CommF_") local AUTO_HIT_RADIUS = 30 local ABOVE_OFFSET = Vector3.new(0, 20, 15) local ATTACK_INTERVAL = 0.001 local ADD_POINT_STAT = "Melee" local ADD_POINT_AMOUNT = 1 local ADD_POINT_INTERVAL = 5 local FRUIT_NAMES = {"Rocket Fruit","Spin Fruit","Blade Fruit","Spring Fruit","Bomb Fruit","Smoke Fruit","Spike Fruit","Flame Fruit","Ice Fruit","Sand Fruit","Dark Fruit","Eagle Fruit","Diamond Fruit","Light Fruit","Rubber Fruit","Ghost Fruit","Magma Fruit","Quake Fruit","Buddha Fruit","Love Fruit","Creation Fruit","Spider Fruit","Sound Fruit","Phoenix Fruit","Portal Fruit","Lightning Fruit","Pain Fruit","Blizzard Fruit","Gravity Fruit","Mammoth Fruit","T-Rex Fruit","Dough Fruit","Shadow Fruit","Venom Fruit","Gas Fruit","Spirit Fruit","Tiger Fruit","Yeti Fruit","Kitsune Fruit","Control Fruit","Dragon Fruit",} local FRUIT_SET = {} for _, name in ipairs(FRUIT_NAMES) do FRUIT_SET[string.lower(name)] = name end local FRUIT_SPEED = 120 local FRUIT_SCAN_INTERVAL = 0.5 local FRUIT_RETRY_DELAY = 0.3 local isTweening = false local currentTween = nil local statusLabel local pendingQuestName = nil local pendingQuestStage = nil local isSearching = false local activeQuestName = nil local activeQuestStage = nil local isReacceptingQuest = false local isFarming = false local farmThread = nil local isAutoActive = false local scanThread = nil local startPostQuestFlow local navigateToQuest local fruitSnipeActive = false local fruitThread = nil local fruitTween = nil local fruitStatusLabel local fruitButton local currentFruitTarget = nil local addPointActive = false local addPointThread = nil local farmPausedForFruit = false local userWantsFarm = false local function getLevel() local data = LocalPlayer:FindFirstChild("Data") if data then local level = data:FindFirstChild("Level") if level and level:IsA("IntValue") then return level.Value end end return 0 end local function getPlayerPosition() local character = LocalPlayer.Character if not character then return nil end local rootPart = character:FindFirstChild("HumanoidRootPart") if not rootPart then return nil end return rootPart.Position end local function getStageIndexForQuest(questName, level) local stages = Quests[questName] if type(stages) ~= "table" then return 1 end local bestIndex = 1 local bestLevelReq = -1 for stageIndex, stage in ipairs(stages) do if type(stage) == "table" and stage.LevelReq and level >= stage.LevelReq then if not stage.MeetsRequirements and stage.LevelReq > bestLevelReq then bestIndex = stageIndex bestLevelReq = stage.LevelReq end end end return bestIndex end local function normalizeQuestLabel(value) local label = string.lower(tostring(value or "")) label = label:gsub("quest%s*giver", "") label = label:gsub("[^%w]", "") label = label:gsub("quest", "") return label end local function findQuestForGiver(npcName, giverLevel) local aliases = {turtleadventure = "deepforestisland",deepforestarea2 = "deepforestisland2",rearcrew = "ship1",frontcrew = "ship2",hydratown = "venomcrew",peanut = "nutsisland",chocolate1 = "choc1",chocolate2 = "choc2",candycane = "candy1",hauntedcastle1 = "haunted1",hauntedcastle2 = "haunted2",graveyard = "zombie",} local label = normalizeQuestLabel(npcName) local matchLabel = aliases[label] or label local bestLevel = -1 local choices = {} for questName, stages in pairs(Quests) do if type(stages) == "table" then for stageIndex, stage in ipairs(stages) do local requiredLevel = stage.LevelReq if type(requiredLevel) == "number" and requiredLevel <= giverLevel then if requiredLevel > bestLevel then bestLevel = requiredLevel table.clear(choices) end if requiredLevel == bestLevel then table.insert(choices, {questName = questName,stageIndex = stageIndex,level = requiredLevel,}) end end end end end if #choices == 0 then return nil end if #choices == 1 then return choices[1].questName, choices[1].stageIndex end local bestChoice = nil local bestScore = 0 local tied = false for _, choice in ipairs(choices) do local key = normalizeQuestLabel(choice.questName) local score = 0 if key == matchLabel then score = 3 elseif #matchLabel > 0 and string.find(key, matchLabel, 1, true) then score = 2 elseif #key > 0 and string.find(matchLabel, key, 1, true) then score = 1 end if score > bestScore then bestChoice = choice bestScore = score tied = false elseif score > 0 and score == bestScore then tied = true end end if bestChoice and bestScore > 0 and not tied then return bestChoice.questName, bestChoice.stageIndex end return nil end local function findRankedQuestGivers() local level = getLevel() local position = getPlayerPosition() if not position then return {} end local npcList = GuideModule.Data and GuideModule.Data.NPCList if type(npcList) ~= "table" then return {} end local candidates = {} for key, npcData in pairs(npcList) do if type(npcData) == "table" and type(npcData.Levels) == "table" and npcData.Position and typeof(npcData.Position) == "Vector3" then local bestLevel = -1 for _, requiredLevel in ipairs(npcData.Levels) do if type(requiredLevel) == "number" and requiredLevel <= level and requiredLevel > bestLevel then bestLevel = requiredLevel end end if bestLevel >= 0 then local npcName = npcData.NPCName or tostring(key) local questName, stageIndex = findQuestForGiver(npcName, bestLevel) if questName then table.insert(candidates, {position = npcData.Position,npcName = npcName,questName = questName,stageIndex = stageIndex,npcKey = key,level = bestLevel,distance = (position - npcData.Position).Magnitude,}) end end end end table.sort(candidates, function(a, b) if a.level ~= b.level then return a.level > b.level end return a.distance < b.distance end) local seen = {} local deduped = {} for _, candidate in ipairs(candidates) do if not seen[candidate.questName] then seen[candidate.questName] = true table.insert(deduped, candidate) end end return deduped end local function npcExistsInWorkspace(npcName) if not npcName then return false end local npcsFolder = Workspace:FindFirstChild("NPCs", true) if not npcsFolder then return false end local target = string.lower(npcName) for _, child in ipairs(npcsFolder:GetDescendants()) do local name = string.lower(child.Name) if name == target or string.find(name, target, 1, true) then return true end end return false end local function waitForNpc(npcName, timeout) timeout = timeout or 10 local deadline = os.clock() + timeout local lastShown while os.clock() < deadline do if npcExistsInWorkspace(npcName) then return true end local remaining = math.max(0, math.ceil(deadline - os.clock())) if remaining ~= lastShown and statusLabel then statusLabel.Text = string.format("Searching for %s... %ds", npcName or "NPC", remaining) lastShown = remaining end task.wait(0.2) end return npcExistsInWorkspace(npcName) end local function acceptQuest(questName, stageIndex) if not CommF_ or not questName then return false end local ok, result = pcall(function() return CommF_:InvokeServer("StartQuest", questName, stageIndex) end) return ok and result ~= false end local function getCharacterFolder() local charFolder = Workspace:FindFirstChild("Characters") if not charFolder then return nil end return charFolder:FindFirstChild(LocalPlayer.Name) end local function setupCharacter() local charFolder = getCharacterFolder() if not charFolder then return false end charFolder:SetAttribute("AttackSpeedMultiplier", 3) for _, armName in ipairs({"LeftLowerArm", "RightLowerArm"}) do local arm = charFolder:FindFirstChild(armName) if arm and arm:IsA("BasePart") then arm.Size = Vector3.new(40, 40, 40) arm.Massless = true arm.Transparency = 0.7 arm.CanCollide = false end end return true end local function ensureAuraEnabled() local character = LocalPlayer.Character if not character or not CommF_ or not character:HasTag("Buso") then return false end if character:FindFirstChild("HasBuso") then return true end local ok = pcall(function() CommF_:InvokeServer("Buso") end) return ok end local function getEnemyNameFromQuest(questName, stageIndex) local stages = Quests[questName] if type(stages) ~= "table" then return nil end local stage = stages[stageIndex] if not stage or not stage.Task then return nil end for enemyName, _ in pairs(stage.Task) do return enemyName end return nil end local function findMatchingEnemies(enemyName) local enemiesFolder = Workspace:FindFirstChild("Enemies") if not enemiesFolder or not enemyName then return {} end local matches = {} local lowerTarget = string.lower(enemyName) for _, enemy in ipairs(enemiesFolder:GetChildren()) do if enemy:IsA("Model") then local nameMatch = enemy.Name == enemyName or string.find(string.lower(enemy.Name), lowerTarget, 1, true) ~= nil if nameMatch then local humanoid = enemy:FindFirstChildOfClass("Humanoid") local enemyRoot = enemy:FindFirstChild("HumanoidRootPart") if humanoid and enemyRoot and humanoid.Health > 0 then table.insert(matches, enemy) end end end end return matches end local function findNearestEnemy(enemyName) local matches = findMatchingEnemies(enemyName) if #matches == 0 then return nil end local playerPos = getPlayerPosition() if not playerPos then return matches[1] end local nearest = nil local nearestDist = math.huge for _, enemy in ipairs(matches) do local root = enemy:FindFirstChild("HumanoidRootPart") if root then local dist = (root.Position - playerPos).Magnitude if dist < nearestDist then nearestDist = dist nearest = enemy end end end return nearest end local function anyEnemyInRadius(enemyName, radius) local playerPos = getPlayerPosition() if not playerPos then return false, nil end local matches = findMatchingEnemies(enemyName) local closest = nil local closestDist = math.huge for _, enemy in ipairs(matches) do local root = enemy:FindFirstChild("HumanoidRootPart") if root then local dist = (root.Position - playerPos).Magnitude if dist <= radius and dist < closestDist then closestDist = dist closest = enemy end end end return closest ~= nil, closest end local function findMeleeInWorkspaceCharacter() local chars = Workspace:FindFirstChild("Characters") if not chars then return nil end local myChar = chars:FindFirstChild(LocalPlayer.Name) if not myChar then return nil end for _, child in ipairs(myChar:GetChildren()) do if child:IsA("Tool") and child.ToolTip == "Melee" then return child end end for _, d in ipairs(myChar:GetDescendants()) do if d:IsA("Tool") and d.ToolTip == "Melee" then return d end end return nil end local function findMeleeInBackpack() local backpack = LocalPlayer:FindFirstChild("Backpack") if not backpack then return nil end for _, child in ipairs(backpack:GetChildren()) do if child:IsA("Tool") and child.ToolTip == "Melee" then return child end end return nil end local function getEquippedWeapon() local melee = findMeleeInWorkspaceCharacter() if melee then return melee end local character = LocalPlayer.Character if character then for _, child in ipairs(character:GetChildren()) do if child:IsA("Tool") and child.ToolTip == "Melee" then return child end end end return nil end local function ensureWeaponEquipped() local equipped = getEquippedWeapon() if equipped then return equipped end local melee = findMeleeInBackpack() if not melee then local backpack = LocalPlayer:FindFirstChild("Backpack") if backpack then for _, child in ipairs(backpack:GetChildren()) do if child:IsA("Tool") then melee = child break end end end end if not melee then return nil end local character = LocalPlayer.Character local humanoid = character and character:FindFirstChildOfClass("Humanoid") if not humanoid then return nil end pcall(function() humanoid:EquipTool(melee) end) local deadline = os.clock() + 0.5 while os.clock() < deadline do local nowEquipped = getEquippedWeapon() if nowEquipped then return nowEquipped end task.wait(0.05) end return getEquippedWeapon() end local function doAttack() local weapon = ensureWeaponEquipped() if weapon then pcall(function() CombatController:Attack(weapon) end) return true end return false end local function startAddPointLoop() if addPointThread then return end addPointActive = true addPointThread = task.spawn(function() while addPointActive do if CommF_ then pcall(function() CommF_:InvokeServer("AddPoint", ADD_POINT_STAT, ADD_POINT_AMOUNT) end) end task.wait(ADD_POINT_INTERVAL) end addPointThread = nil end) end local function stopAddPointLoop() addPointActive = false if addPointThread then task.cancel(addPointThread) addPointThread = nil end end local function stopFarming() isFarming = false local character = LocalPlayer.Character if character then character:SetAttribute("QuestNavigatorMultiHit", nil) end if farmThread then task.cancel(farmThread) farmThread = nil end end local function tweenToPosition(targetPosition) local character = LocalPlayer.Character if not character then return false end local rootPart = character:FindFirstChild("HumanoidRootPart") if not rootPart then return false end local startPos = rootPart.Position local distance = (targetPosition - startPos).Magnitude local speed = 120 local duration = distance / speed if duration < 0.1 then duration = 0.1 end if currentTween then currentTween:Cancel() currentTween = nil end local goal = { CFrame = CFrame.new(targetPosition) } local tweenInfo = TweenInfo.new(duration, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, 0, false, 0) currentTween = TweenService:Create(rootPart, tweenInfo, goal) isTweening = true currentTween.Completed:Connect(function(playbackState) isTweening = false currentTween = nil if playbackState == Enum.PlaybackState.Completed then if pendingQuestName then local level = getLevel() local stageIndex = pendingQuestStage or getStageIndexForQuest(pendingQuestName, level) if statusLabel then statusLabel.Text = "Accepting quest: " .. pendingQuestName .. "..." end task.wait(0.5) local accepted = acceptQuest(pendingQuestName, stageIndex) if statusLabel then if accepted then statusLabel.Text = "Quest accepted: " .. pendingQuestName .. " (Stage " .. stageIndex .. ")" else statusLabel.Text = "Failed to accept quest!" end end local questName = pendingQuestName pendingQuestName = nil pendingQuestStage = nil if accepted then activeQuestName = questName activeQuestStage = stageIndex startPostQuestFlow(questName, stageIndex) end elseif statusLabel then statusLabel.Text = "Arrived at quest giver!" end end end) currentTween:Play() return true end startPostQuestFlow = function(questName, stageIndex) local enemyName = getEnemyNameFromQuest(questName, stageIndex) if not enemyName then if statusLabel then statusLabel.Text = "No enemy target found for quest!" end return end stopFarming() setupCharacter() ensureAuraEnabled() local character = LocalPlayer.Character if character then character:SetAttribute("QuestNavigatorMultiHit", true) end isFarming = true farmThread = task.spawn(function() local lastAttackTime = 0 local currentTarget = nil while isFarming do local now = os.clock() local character = LocalPlayer.Character local playerRoot = character and character:FindFirstChild("HumanoidRootPart") if playerRoot then local targets = findMatchingEnemies(enemyName) if currentTarget and not table.find(targets, currentTarget) then currentTarget = nil end if not currentTarget and #targets > 0 then currentTarget = findNearestEnemy(enemyName) elseif not currentTarget and #targets == 0 and statusLabel then statusLabel.Text = "Searching for " .. enemyName .. "..." end if currentTarget then local humanoid = currentTarget:FindFirstChildOfClass("Humanoid") local enemyRoot = currentTarget:FindFirstChild("HumanoidRootPart") if not humanoid or humanoid.Health <= 0 or not enemyRoot then currentTarget = nil else local abovePosition = enemyRoot.Position + ABOVE_OFFSET local followOffset = abovePosition - playerRoot.Position local horizontalOffset = Vector3.new(followOffset.X, 0, followOffset.Z) if (horizontalOffset.Magnitude > 0.75 or math.abs(followOffset.Y) > 0.75) and not isTweening then if statusLabel then statusLabel.Text = "Tweening above " .. currentTarget.Name .. "..." end if not tweenToPosition(abovePosition) then currentTarget = nil end end end end local inRange, rangeEnemy = anyEnemyInRadius(enemyName, AUTO_HIT_RADIUS) local shouldAttack = inRange or (currentTarget ~= nil) if shouldAttack and (now - lastAttackTime >= ATTACK_INTERVAL) then lastAttackTime = now if doAttack() and statusLabel then local labelEnemy = rangeEnemy or currentTarget local name = labelEnemy and labelEnemy.Name or enemyName if isTweening then statusLabel.Text = "Attacking" .. name elseif inRange then statusLabel.Text = "Attacking" .. name else statusLabel.Text = "Attacking" .. name end end end elseif statusLabel then statusLabel.Text = "Waiting for character" end task.wait(0.05) end end) end navigateToQuest = function() if isTweening or isFarming or isSearching then return end isSearching = true if statusLabel then statusLabel.Text = "Finding quest giver" end local rankedGivers = findRankedQuestGivers() if #rankedGivers == 0 then isSearching = false if statusLabel then statusLabel.Text = "No eligible quest giver found" end return end local currentGiver = rankedGivers[1] local npcName = currentGiver.npcName or "quest NPC" local npcFound = waitForNpc(npcName, 10) if not isSearching then return end isSearching = false local questName = currentGiver.questName local stageIndex = 1 if not questName or not stageIndex then if statusLabel then statusLabel.Text = "No quest is configured for " .. npcName end return end local displayQuestName = (Quests[questName][stageIndex] and Quests[questName][stageIndex].Name) or questName if not npcFound then stageIndex = 1 displayQuestName = (Quests[questName][stageIndex] and Quests[questName][stageIndex].Name) or questName end pendingQuestName = questName pendingQuestStage = stageIndex if statusLabel then if npcFound then statusLabel.Text = "NPC found; traveling to " .. npcName else statusLabel.Text = "10s elapsed; next quest: " .. displayQuestName end end if not tweenToPosition(currentGiver.position) then pendingQuestName = nil pendingQuestStage = nil if statusLabel then statusLabel.Text = "Couldn't reach the quest location" end end end local isRespawnRecoveryRunning = false LocalPlayer.CharacterAdded:Connect(function(character) if not isAutoActive or isRespawnRecoveryRunning then return end isRespawnRecoveryRunning = true isSearching = true task.spawn(function() local rootPart = character:WaitForChild("HumanoidRootPart", 10) if not rootPart then isSearching = false isRespawnRecoveryRunning = false return end local characters = Workspace:FindFirstChild("Characters") if characters then characters:WaitForChild(LocalPlayer.Name, 10) end task.wait(0.25) if not isAutoActive then isSearching = false isRespawnRecoveryRunning = false return end if currentTween then currentTween:Cancel() currentTween = nil end isTweening = false if activeQuestName and activeQuestStage then local questName = activeQuestName local stageIndex = activeQuestStage local accepted = acceptQuest(questName, stageIndex) isSearching = false if accepted then startPostQuestFlow(questName, stageIndex) else activeQuestName = nil activeQuestStage = nil navigateToQuest() end else pendingQuestName = nil pendingQuestStage = nil isSearching = false navigateToQuest() end isRespawnRecoveryRunning = false end) end) local function startQuestScan() if scanThread then return end isAutoActive = true startAddPointLoop() scanThread = task.spawn(function() while isAutoActive do if not isTweening and not isSearching then local rankedGivers = findRankedQuestGivers() if #rankedGivers > 0 then local best = rankedGivers[1] local bestQuest = best.questName local shouldSwitch = false if not activeQuestName then shouldSwitch = true elseif bestQuest ~= activeQuestName then local currentLevel = -1 local bestLevel = best.level or -1 if activeQuestName and Quests[activeQuestName] and activeQuestStage then local stage = Quests[activeQuestName][activeQuestStage] if stage and stage.LevelReq then currentLevel = stage.LevelReq end end if bestLevel > currentLevel then shouldSwitch = true end end if shouldSwitch then if statusLabel then statusLabel.Text = "Next quest found: " .. (best.npcName or bestQuest) end stopFarming() activeQuestName = nil activeQuestStage = nil navigateToQuest() end end end task.wait(1) end scanThread = nil end) end local function stopQuestScan() isAutoActive = false if scanThread then task.cancel(scanThread) scanThread = nil end stopAddPointLoop() end local QuestUpdate = Remotes:FindFirstChild("QuestUpdate") if QuestUpdate then QuestUpdate.OnClientEvent:Connect(function(_, context) if type(context) ~= "table" or context.Context ~= "Complete" then return end if isReacceptingQuest or not activeQuestName or not activeQuestStage then return end isReacceptingQuest = true local questName = activeQuestName local stageIndex = activeQuestStage task.spawn(function() stopFarming() task.wait(0.25) local accepted = acceptQuest(questName, stageIndex) if accepted then if statusLabel then local stage = Quests[questName] and Quests[questName][stageIndex] statusLabel.Text = "Quest restarted: " .. ((stage and stage.Name) or questName) end startPostQuestFlow(questName, stageIndex) elseif statusLabel then statusLabel.Text = "Quest finished; restart request failed" end isReacceptingQuest = false end) end) end local function matchFruitName(instanceName) if type(instanceName) ~= "string" then return nil end local lower = string.lower(instanceName) if FRUIT_SET[lower] then return FRUIT_SET[lower] end for key, pretty in pairs(FRUIT_SET) do if string.find(lower, key, 1, true) then return pretty end end return nil end local function resolvePart(instance) if not instance then return nil end if instance:IsA("BasePart") then return instance end if instance:IsA("Tool") then return instance:FindFirstChild("Handle") or instance:FindFirstChildWhichIsA("BasePart", true) end if instance:IsA("Model") then return instance.PrimaryPart or instance:FindFirstChild("Handle") or instance:FindFirstChild("HumanoidRootPart") or instance:FindFirstChildWhichIsA("BasePart", true) end return instance:FindFirstChildWhichIsA("BasePart", true) end local function findMatchingFruits() local results = {} local seen = {} local function scan(container) if not container then return end for _, child in ipairs(container:GetChildren()) do if not seen[child] then seen[child] = true local pretty = matchFruitName(child.Name) if pretty then local part = resolvePart(child) if part and part.Parent then table.insert(results, {instance = child,part = part,prettyName = pretty,}) end end if child:IsA("Folder") or child:IsA("Model") or child:IsA("Tool") then if not child:FindFirstChildOfClass("Humanoid") then scan(child) end end end end end scan(Workspace) return results end local function findNearestFruit() local fruits = findMatchingFruits() if #fruits == 0 then return nil end local playerPos = getPlayerPosition() if not playerPos then return fruits[1] end local nearest, nearestDist = nil, math.huge for _, fruit in ipairs(fruits) do if fruit.part and fruit.part.Parent then local dist = (fruit.part.Position - playerPos).Magnitude if dist < nearestDist then nearestDist = dist nearest = fruit end end end return nearest end local function tweenToFruit(fruit) local character = LocalPlayer.Character if not character then return false end local rootPart = character:FindFirstChild("HumanoidRootPart") if not rootPart then return false end if not fruit or not fruit.part or not fruit.part.Parent then return false end local targetPos = fruit.part.Position + Vector3.new(0, 3, 0) local startPos = rootPart.Position local distance = (targetPos - startPos).Magnitude local duration = distance / FRUIT_SPEED if duration < 0.1 then duration = 0.1 end if duration > 5 then duration = 5 end if fruitTween then pcall(function() fruitTween:Cancel() end) fruitTween = nil end local ok = pcall(function() rootPart.CFrame = CFrame.new(targetPos) end) if ok then task.wait(0.15) return true end local goal = { CFrame = CFrame.new(targetPos) } local tweenInfo = TweenInfo.new(duration, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, 0, false, 0) fruitTween = TweenService:Create(rootPart, tweenInfo, goal) fruitTween:Play() local done = false local conn conn = fruitTween.Completed:Connect(function() done = true if conn then conn:Disconnect() end end) local deadline = os.clock() + duration + 2 while not done and os.clock() < deadline do if not fruit.part or not fruit.part.Parent then break end task.wait(0.05) end if fruitTween then pcall(function() fruitTween:Cancel() end) fruitTween = nil end return true end local function startFruitSnipe() if fruitThread then return end fruitThread = task.spawn(function() while fruitSnipeActive do local fruit = findNearestFruit() if fruit and (isFarming or isAutoActive or activeQuestName) then stopFarming() if currentTween then currentTween:Cancel() currentTween = nil end isTweening = false pendingQuestName = nil pendingQuestStage = nil stopAddPointLoop() farmPausedForFruit = true if statusLabel then statusLabel.Text = "Fruit found - pausing farm" end end if fruit then currentFruitTarget = fruit if fruitStatusLabel then fruitStatusLabel.Text = "TP -> " .. fruit.prettyName end tweenToFruit(fruit) task.wait(FRUIT_RETRY_DELAY) if farmPausedForFruit and fruitSnipeActive then farmPausedForFruit = false if userWantsFarm then startQuestScan() if activeQuestName and activeQuestStage then local qn = activeQuestName local si = activeQuestStage local accepted = acceptQuest(qn, si) if accepted then startPostQuestFlow(qn, si) else navigateToQuest() end else navigateToQuest() end end end else currentFruitTarget = nil if fruitStatusLabel then fruitStatusLabel.Text = "Watching for fruits..." end task.wait(FRUIT_SCAN_INTERVAL) end end currentFruitTarget = nil if fruitStatusLabel then fruitStatusLabel.Text = "Idle" end end) end local function stopFruitSnipe() fruitSnipeActive = false currentFruitTarget = nil farmPausedForFruit = false if fruitTween then pcall(function() fruitTween:Cancel() end) fruitTween = nil end if fruitThread then task.cancel(fruitThread) fruitThread = nil end if fruitStatusLabel then fruitStatusLabel.Text = "Idle" end end local function toggleFruitSnipe() if fruitSnipeActive then stopFruitSnipe() else fruitSnipeActive = true startFruitSnipe() end end do local gui = Instance.new("ScreenGui") gui.Name = "QNGui" gui.ResetOnSpawn = false gui.Parent = LocalPlayer:WaitForChild("PlayerGui") local panel = Instance.new("Frame") panel.Name = "Panel" panel.Size = UDim2.new(0, 180, 0, 170) panel.Position = UDim2.new(0, 20, 0, 100) panel.BackgroundColor3 = Color3.fromRGB(35, 35, 35) panel.BorderColor3 = Color3.fromRGB(0, 0, 0) panel.BorderSizePixel = 1 panel.Active = true panel.Draggable = true panel.Parent = gui local title = Instance.new("TextLabel") title.Name = "Title" title.Size = UDim2.new(1, 0, 0, 20) title.Position = UDim2.new(0, 0, 0, 0) title.BackgroundColor3 = Color3.fromRGB(50, 50, 50) title.BorderSizePixel = 0 title.Text = "Quest Navigator" title.TextColor3 = Color3.fromRGB(255, 255, 255) title.TextSize = 13 title.Font = Enum.Font.SourceSans title.Parent = panel local questBtn = Instance.new("TextButton") questBtn.Name = "QuestButton" questBtn.Size = UDim2.new(1, -20, 0, 32) questBtn.Position = UDim2.new(0, 10, 0, 30) questBtn.BackgroundColor3 = Color3.fromRGB(0, 120, 215) questBtn.BorderColor3 = Color3.fromRGB(0, 0, 0) questBtn.BorderSizePixel = 1 questBtn.Text = "Start Quest" questBtn.TextColor3 = Color3.fromRGB(255, 255, 255) questBtn.TextSize = 14 questBtn.Font = Enum.Font.SourceSans questBtn.Parent = panel statusLabel = Instance.new("TextLabel") statusLabel.Name = "Status" statusLabel.Size = UDim2.new(1, -20, 0, 16) statusLabel.Position = UDim2.new(0, 10, 0, 66) statusLabel.BackgroundTransparency = 1 statusLabel.Text = "Idle" statusLabel.TextColor3 = Color3.fromRGB(220, 220, 220) statusLabel.TextSize = 12 statusLabel.Font = Enum.Font.SourceSans statusLabel.TextXAlignment = Enum.TextXAlignment.Left statusLabel.Parent = panel local fruitBtn = Instance.new("TextButton") fruitBtn.Name = "FruitButton" fruitBtn.Size = UDim2.new(1, -20, 0, 32) fruitBtn.Position = UDim2.new(0, 10, 0, 90) fruitBtn.BackgroundColor3 = Color3.fromRGB(0, 120, 215) fruitBtn.BorderColor3 = Color3.fromRGB(0, 0, 0) fruitBtn.BorderSizePixel = 1 fruitBtn.Text = "Start Fruit Sniper" fruitBtn.TextColor3 = Color3.fromRGB(255, 255, 255) fruitBtn.TextSize = 14 fruitBtn.Font = Enum.Font.SourceSans fruitBtn.Parent = panel fruitButton = fruitBtn fruitStatusLabel = Instance.new("TextLabel") fruitStatusLabel.Name = "FruitStatus" fruitStatusLabel.Size = UDim2.new(1, -20, 0, 16) fruitStatusLabel.Position = UDim2.new(0, 10, 0, 126) fruitStatusLabel.BackgroundTransparency = 1 fruitStatusLabel.Text = "Idle" fruitStatusLabel.TextColor3 = Color3.fromRGB(220, 220, 220) fruitStatusLabel.TextSize = 12 fruitStatusLabel.Font = Enum.Font.SourceSans fruitStatusLabel.TextXAlignment = Enum.TextXAlignment.Left fruitStatusLabel.Parent = panel local hint = Instance.new("TextLabel") hint.Size = UDim2.new(1, -20, 0, 12) hint.Position = UDim2.new(0, 10, 1, -16) hint.BackgroundTransparency = 1 hint.Text = "rctrl = quest   rshift = fruit" hint.TextColor3 = Color3.fromRGB(150, 150, 150) hint.TextSize = 10 hint.Font = Enum.Font.SourceSans hint.TextXAlignment = Enum.TextXAlignment.Left hint.Parent = panel local function stopAll() isSearching = false if currentTween then currentTween:Cancel() currentTwee